class LmdbCurrentAliasCacheIdentityTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void exactPreparedCacheRetainsTheCurrentVisibleValue(boolean trusted, @TempDir Path directory) {
		Object origin = new Object();
		BNode first = trusted ? remote("current-a-", origin) : VF.createBNode("current-a");
		BNode second = trusted ? remote("current-b-", origin) : VF.createBNode("current-b");
		assertNotEquals(first.getID(), second.getID());
		if (trusted) {
			assertTrue(RemoteBNode.sameTrustedIdentity((RemoteBNode) first, (RemoteBNode) second));
		}
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile()));
		repository.init();
		try (var connection = repository.getConnection()) {
			connection.add(VF.createIRI("urn:current:s"), VF.createIRI("urn:current:p"), VF.createLiteral("left"));
			connection.add(VF.createIRI("urn:current:s"), VF.createIRI("urn:current:q"), VF.createLiteral("right"));
			TupleQuery query = connection.prepareTupleQuery("SELECT ?value WHERE { "
					+ "?s <urn:current:p> ?o . ?s <urn:current:q> ?other . BIND(?input AS ?value) }");
			query.setBinding("input", first);
			assertCurrentValue(query, first, trusted);
			TupleExpr warmed = (TupleExpr) query.explain(Explanation.Level.Optimized).tupleExpr();
			assertEquals("true", warmed.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"),
					"the same prepared input must prove the real native cache route before rebinding");
			for (BNode current : List.of(second, first, second)) {
				query.setBinding("input", current);
				assertCurrentValue(query, current, trusted);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void assertCurrentValue(TupleQuery query, BNode current, boolean trusted) {
		try (var rows = query.evaluate()) {
			assertTrue(rows.hasNext());
			Value actual = rows.next().getValue("value");
			assertEquals(current.getID(), assertInstanceOf(BNode.class, actual).getID(),
					"canonical authority must not substitute a previous invocation's visible alias");
			if (trusted) {
				assertTrue(RemoteBNode.sameTrustedIdentity((RemoteBNode) current,
						assertInstanceOf(RemoteBNode.class, actual)));
			}
			assertFalse(rows.hasNext());
		}
	}

	private static BNode remote(String namespace, Object origin) {
		return (BNode) RemoteBNode.newResponseScope(new BlankNodeAllocationScope(namespace, id -> false), VF,
				origin, true).map(VF.createBNode("canonical"));
	}
}
